using namespace clash_native;
struct StateTestQ {
    PfEntity* e;PfTargeting* t;bool route=true,hasHP=true;int prepare=0,gates=0,attackExit=0,deployEntry=0,scaled=50;
    void prepare_route(){++prepare;}void combat_gate(){++gates;}void attacking_exit(){++attackExit;}void deploying_entry(){++deployEntry;}
    bool may_hold_route(){return route;}bool grid_route_flag(){return false;}bool grid_allows_route(bool){return true;}bool has_hit_points(){return hasHP;}int scaled_deploy_step_ms(){return scaled;}
    void clear_reference(){t->reference=-1;}
};
extern "C" void rules_state_visit(const int*in,int n,int*out){for(int i=0;i<n;++i){const int*p=in+12*i;PfEntity e{};e.state=p[0];e.deployCountdown=p[1];e.delay=p[2];e.pendingDamageDurationMs=p[3];StateTimers timers{};timers.spawnImmune=p[4];timers.spawnImmuneElapsedMs=p[5];timers.dashImmunityRemainingMs=p[6];StateVisitConfig c{};c.deployTimeMs=p[7];c.kingTowerMiddle=p[10];StateTestQ q{&e,nullptr,bool(p[8]),bool(p[9])};int tail=state_visit(e,timers,nullptr,nullptr,c,q);int row[]={e.state,e.deployCountdown,e.delay,e.pendingDamageDurationMs,int(timers.spawnImmune),timers.spawnImmuneElapsedMs,timers.dashImmunityRemainingMs,int(timers.removalRequested),tail,q.gates};for(int k=0;k<10;++k)out[10*i+k]=row[k];}}
extern "C" void rules_state_set(const int*in,int n,int*out){for(int i=0;i<n;++i){const int*p=in+9*i;PfEntity e{};e.state=p[0];e.deployCountdown=p[1];e.movementComponent=true;PfMovement m{};m.route.add(3);m.route.add(5);m.routeLeadsAway=1;PfTargeting t{};t.targetLostTimerMs=p[3];t.targetingComponentActive=p[4];StateVisitConfig c{};c.deployTimeMs=p[5];StateTestQ q{&e,&t};int changed=state_set(e,p[6]?&m:nullptr,&t,c,p[2],q);int row[]={e.state,e.deployCountdown,e.movementActive,t.targetLostTimerMs,m.route.count,m.routeLeadsAway,q.prepare,q.gates,q.attackExit,q.deployEntry,changed};for(int k=0;k<11;++k)out[11*i+k]=row[k];}}
extern "C" void rules_combat_gate(const int*in,int n,int*out){for(int i=0;i<n;++i){const int*p=in+7*i;PfEntity e{};e.state=p[0];e.deployCountdown=p[1];e.flags=p[2];PfTargeting t{};t.reference=p[6]?1:-1;StateTestQ q{&e,&t};bool on=combat_gate(e,t,p[3],p[4],p[5],true,1,q);out[2*i]=on;out[2*i+1]=t.reference>=0;}}
extern "C" void rules_king_activation(int trigger,int n,int initialListed,int*out){KingActivation king{};king.waitQueued=!initialListed;king.waitListed=initialListed;for(int tick=0;tick<n;++tick){auto before=king.tags(1,2);king.pending_pass();king.run_pass(tick>=trigger);king.pending_pass();king.pending_pass();int row[]={int(before),int(king.tags(1,2)),king.waitListed,king.waitFinished,king.activationListed,king.activationFinished,int(king.activationCounter),king.active()};for(int k=0;k<8;++k)out[8*tick+k]=row[k];}}
